<?php
namespace App\Services;
use App\Models\Language;use Illuminate\Http\Request;use Illuminate\Support\Facades\Cache;
class LanguageContext {public function current(Request $r):Language{$code=$r->session()->get('language_code');$l=$code?Language::where('code',$code)->where('is_active',true)->first():null;return $l??Cache::remember('language.default',60,fn()=>Language::where('is_active',true)->where('is_default',true)->first()??Language::where('is_active',true)->first()??new Language(['code'=>config('app.locale','en'),'name'=>'English','native_name'=>'English','direction'=>'ltr']));}public function active(){return Cache::remember('language.active',60,fn()=>Language::where('is_active',true)->orderBy('sort_order')->orderBy('name')->get());}public function select(Request $r,string $code):bool{$l=Language::where('code',strtolower($code))->where('is_active',true)->first();if(!$l)return false;$r->session()->put('language_code',$l->code);return true;}public function clear():void{Cache::forget('language.default');Cache::forget('language.active');}}
